<script setup lang="ts">
import { useGameMode } from '~/composables/useGameMode'
const store = useCampaignStore(); const api = useCompanionApi(); const gameMode = useGameMode(); const busy = ref(false); const error = ref('')
const drafts = reactive<Record<string, { name: string; modifier: number; hitPoints: number | null; maxHitPoints: number | null }>>({})
watch(() => store.snapshot?.activeEncounter?.combatants, (combatants) => { for (const combatant of combatants ?? []) drafts[combatant.id] = { name: combatant.name, modifier: combatant.initiativeModifier, hitPoints: combatant.currentHitPoints, maxHitPoints: combatant.maxHitPoints } }, { immediate: true, deep: true })
async function reroll(combatantId: string | null = null) { const encounter=store.snapshot?.activeEncounter; if(!store.session||!encounter)return; busy.value=true;error.value='';try{store.snapshot!.activeEncounter=await api.rollInitiative(store.session,encounter.id,combatantId)}catch(e){error.value=(e as Error).message}finally{busy.value=false} }
async function saveCombatant(combatantId:string){const encounter=store.snapshot?.activeEncounter;const draft=drafts[combatantId];const current=encounter?.combatants.find(item=>item.id===combatantId);if(!store.session||!encounter||!draft||!current)return;busy.value=true;error.value='';try{store.snapshot!.activeEncounter=encounter.status==='Active'&&draft.name===current.name&&draft.modifier===current.initiativeModifier&&draft.hitPoints!==null&&draft.maxHitPoints===current.maxHitPoints?await api.updateHitPoints(store.session,encounter.id,combatantId,draft.hitPoints):await api.updateCombatant(store.session,encounter.id,combatantId,draft.name,draft.modifier,draft.hitPoints,draft.maxHitPoints)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function removeCombatant(combatantId:string){const encounter=store.snapshot?.activeEncounter;if(!store.session||!encounter)return;busy.value=true;error.value='';try{store.snapshot!.activeEncounter=await api.removeCombatant(store.session,encounter.id,combatantId);delete drafts[combatantId]}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function saveOwnHitPoints(combatantId:string){const encounter=store.snapshot?.activeEncounter;const draft=drafts[combatantId];if(!store.session||!encounter||draft?.hitPoints===null||draft?.hitPoints===undefined)return;busy.value=true;error.value='';try{store.snapshot!.activeEncounter=await api.updateHitPoints(store.session,encounter.id,combatantId,draft.hitPoints)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function update(action:'next'|'end'){const encounter=store.snapshot?.activeEncounter;if(!store.session||!encounter)return;busy.value=true;error.value='';try{store.snapshot!.activeEncounter=action==='next'?await api.nextTurn(store.session,encounter.id):await api.endEncounter(store.session,encounter.id);if(action==='end')store.snapshot!.activeEncounter=null}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function hpText(current: number | null, max: number | null | undefined) { return max != null ? `Vida ${current}/${max}` : `Vida ${current}` }
</script>
<template>
  <section v-if="store.snapshot?.activeEncounter" class="panel initiative-panel" aria-labelledby="initiative-title">
    <div class="panel-heading"><div><p class="eyebrow">Combate</p><h2 id="initiative-title">Iniciativa</h2></div><span class="round-pill">{{ store.snapshot.activeEncounter.status === 'Active' ? `Rodada ${store.snapshot.activeEncounter.round}` : 'Preparando' }}</span></div>
    <ol class="initiative-list"><li v-for="combatant in store.snapshot.activeEncounter.combatants" :key="combatant.id" :class="{ current: combatant.isCurrent, defeated: combatant.isDefeated }">
      <span class="initiative-value">{{ combatant.initiative ?? '—' }}</span>
      <span v-if="store.damageEffects?.[combatant.id]" :key="store.damageEffects?.[combatant.id]!.nonce" class="damage-pop" role="status" @animationend="store.clearDamageEffect(combatant.id, store.damageEffects?.[combatant.id]?.nonce)" :aria-label="`${combatant.name} sofreu ${store.damageEffects?.[combatant.id]!.amount} de dano`">-{{ store.damageEffects?.[combatant.id]!.amount }}</span>
      <span v-if="!store.isMaster">{{ combatant.name }}<small>Mod. {{ combatant.initiativeModifier >= 0 ? '+' : '' }}{{ combatant.initiativeModifier }}</small><span v-if="combatant.currentHitPoints !== null && combatant.participantId === store.session?.participantId && !gameMode.active.value" class="own-hit-points"><label :for="`own-combat-hit-points-${combatant.id}`">Vida</label><input :id="`own-combat-hit-points-${combatant.id}`" v-model.number="drafts[combatant.id]!.hitPoints" type="number" min="0" max="99999"><button class="initiative-reroll" :disabled="busy" type="button" :aria-label="`Salvar vida de ${combatant.name}`" @click="saveOwnHitPoints(combatant.id)">✓</button></span><span v-else-if="combatant.currentHitPoints !== null" class="own-hit-points-readonly">{{ hpText(combatant.currentHitPoints, combatant.maxHitPoints) }}</span></span>
      <span v-else-if="gameMode.active.value" class="combatant-readonly">{{ combatant.name }}<small>Mod. {{ combatant.initiativeModifier >= 0 ? '+' : '' }}{{ combatant.initiativeModifier }}</small><span v-if="combatant.currentHitPoints !== null">{{ hpText(combatant.currentHitPoints, combatant.maxHitPoints) }}</span></span>
      <span v-else class="combatant-editor"><input v-if="drafts[combatant.id]" v-model="drafts[combatant.id]!.name" :aria-label="`Nome de ${combatant.name}`" maxlength="60"><input v-if="drafts[combatant.id]" v-model.number="drafts[combatant.id]!.modifier" :aria-label="`Modificador de ${combatant.name}`" type="number" min="-100" max="100"><input v-if="drafts[combatant.id]" v-model.number="drafts[combatant.id]!.hitPoints" :aria-label="`Vida de ${combatant.name}`" type="number" min="0" max="99999"><input v-if="drafts[combatant.id]" v-model.number="drafts[combatant.id]!.maxHitPoints" :aria-label="`Vida máxima de ${combatant.name}`" type="number" min="0" max="99999" placeholder="Vida máx."></span>
      <span class="initiative-actions"><button v-if="store.isMaster" class="initiative-reroll" :disabled="busy" type="button" :aria-label="`Rolar iniciativa novamente para ${combatant.name}`" title="Rolar novamente" @click="reroll(combatant.id)">↻</button><button v-if="store.isMaster" class="initiative-reroll" :disabled="busy" type="button" :aria-label="`Salvar ${combatant.name}`" title="Salvar" @click="saveCombatant(combatant.id)">✓</button><button v-if="store.isMaster" class="initiative-reroll danger" :disabled="busy" type="button" :aria-label="`Remover ${combatant.name}`" title="Remover" @click="removeCombatant(combatant.id)">×</button><span v-if="combatant.isCurrent" class="turn-marker">Turno</span></span>
    </li></ol>
    <div v-if="store.isMaster && store.snapshot.activeEncounter.status === 'Active'" class="button-row"><button class="button ghost" :disabled="busy" type="button" @click="reroll()">Rolar todas novamente</button><button class="button primary" :disabled="busy" type="button" @click="update('next')">Próximo turno</button><button class="button ghost danger" :disabled="busy" type="button" @click="update('end')">Encerrar</button></div>
    <p v-if="error" class="form-error" role="alert">{{ error }}</p>
  </section>
</template>